import {HEROES, ATTACKS, DEFENSES, createGame, legalTargets, availableAttacks, availableDefenses, previewDefense, playerAttack, resolveAiDefense, chooseAiAttack, playerDefend, describeState} from './engine.js';
import {icon, portrait, castleArt, landscape} from './art.js';

const $=id=>document.getElementById(id);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='kale-muhafizlari-v1';
const types={stone:'Taş',arrow:'Ok',sound:'Ses',rally:'Temel',universal:'Evrensel'};
const typeIcons={stone:'stone',arrow:'arrow',sound:'sound',rally:'flag',universal:'shield'};
const castleNames={left:'Sol kule',main:'Ana kale',right:'Sağ kule'};
const ids=['kora','ilda','neris'];
let settings={sound:false,trainingEnabled:true,bestTraining:0};
let state,selectedAttack='kora',selectedDefense='brace',selectedTarget='left',busy=false,generation=0,timers=new Set(),audioContext,trainingFrame=0,trainingSession=null,finishShown=false,modalGeneration=0;
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
let storageAvailable=true;
function storageRead(){try{return JSON.parse(localStorage.getItem(STORE)||'null')}catch{return null}}
function validState(s){try{
 if(s?.version!==1||!['playerAttack','aiDefense','aiAttack','playerDefense','finished'].includes(s.phase)||!Number.isInteger(s.round)||s.round<1||s.round>10000||!Number.isInteger(s.rng))return false;
 for(const side of ['player','enemy']){
  if(!Array.isArray(s.castles?.[side])||s.castles[side].length!==3)return false;
  for(const id of ['left','main','right']){const c=s.castles[side].find(c=>c.id===id);if(!c||c.maxHp!==(id==='main'?420:240)||!Number.isFinite(c.hp)||c.hp<0||c.hp>c.maxHp)return false;}
  for(const id of ids){const h=s.heroes?.[side]?.[id];if(!h||!['left','main','right'].includes(h.castleId)||!['attackCd','defenseCd','retreatRounds','retreatUntilRound'].every(k=>Number.isInteger(h[k])&&h[k]>=0&&h[k]<=10002))return false;}
 }
 if(!s.training||!['power','defense'].every(k=>Number.isInteger(s.training[k])&&s.training[k]>=0&&s.training[k]<=3)||!Array.isArray(s.log)||s.log.some(x=>typeof x!=='string'))return false;
 if(['aiDefense','playerDefense'].includes(s.phase)){const p=s.pendingAttack;if(!p||!ATTACKS[p.attackId]||!['left','main','right'].includes(p.targetId)||p.side!==(s.phase==='aiDefense'?'player':'enemy')||!Number.isFinite(p.damage)||p.damage<0||p.damage>100)return false;}
 if(s.phase==='finished'&&!['player','enemy'].includes(s.winner))return false;
 return true;
}catch{return false}}
const saved=storageRead();
if(saved?.settings){settings.sound=saved.settings.sound===true;settings.trainingEnabled=saved.settings.trainingEnabled!==false;settings.bestTraining=Math.max(0,Math.min(3,Math.trunc(Number(saved.settings.bestTraining)||0)));}
function freshGame(){return createGame({seed:`duel-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,training:{power:settings.bestTraining,defense:settings.bestTraining},trainingEnabled:settings.trainingEnabled});}
state=validState(saved?.state)?saved.state:freshGame();
function persist(){try{localStorage.setItem(STORE,JSON.stringify({settings,state}));}catch{storageAvailable=false;}}
function schedule(fn,ms){const token=generation;const id=setTimeout(()=>{timers.delete(id);if(token!==generation)return;if($('modal').open){schedule(fn,150);return;}fn();},ms);timers.add(id);}
function cancelTimers(){generation++;for(const t of timers)clearTimeout(t);timers.clear();$('effects').innerHTML='';}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function announce(message){$('live-status').textContent=message;}
function sound(kind){if(!settings.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime;const tones=kind==='win'?[392,494,587,784]:kind==='defend'?[330,494]:kind==='hit'?[95,65]:[220];tones.forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=kind==='hit'?'triangle':'sine';o.frequency.setValueAtTime(freq,now+i*.09);g.gain.setValueAtTime(0,now+i*.09);g.gain.linearRampToValueAtTime(.055,now+i*.09+.02);g.gain.exponentialRampToValueAtTime(.001,now+i*.09+.22);o.connect(g);g.connect(audioContext.destination);o.start(now+i*.09);o.stop(now+i*.09+.24);});}catch{}}
function setSoundIcon(){$('sound-button').innerHTML=icon(settings.sound?'volume':'mute');$('sound-button').setAttribute('aria-label',settings.sound?'Sesi kapat':'Sesi aç');$('sound-button').title=settings.sound?'Sesi kapat':'Sesi aç';$('sound-button').setAttribute('aria-pressed',String(settings.sound));}
$('landscape').innerHTML=landscape;$('help-button').innerHTML=icon('help');$('settings-button').innerHTML=icon('settings');$('close-modal').innerHTML=icon('close');setSoundIcon();
function safeSelection(){const attacks=availableAttacks(state,'player');if(!attacks.find(a=>a.id===selectedAttack&&a.available))selectedAttack=attacks.find(a=>a.available&&a.id!=='rally')?.id||'rally';const targets=legalTargets(state,'player');if(!targets.some(c=>c.id===selectedTarget))selectedTarget=targets.find(c=>c.id==='main')?.id||targets[0]?.id||'left';if(state.phase==='playerDefense'){const defenses=availableDefenses(state,'player');if(!defenses.find(d=>d.id===selectedDefense&&d.available))selectedDefense='brace';}}
function renderCastles(side){const targetable=side==='enemy'&&state.phase==='playerAttack'&&!busy;const legal=legalTargets(state,side==='enemy'?'player':'enemy').map(c=>c.id);return state.castles[side].map(c=>{
 const locked=c.id==='main'&&!legal.includes('main')&&c.hp>0&&state.phase!=='finished';const selected=targetable&&c.id===selectedTarget;const stationed=ids.filter(id=>state.heroes[side][id].castleId===c.id);const incoming=state.phase==='playerDefense'&&side==='player'&&state.pendingAttack?.targetId===c.id;
 return `<button class="castle-button ${c.id==='main'?'main':''} ${c.hp<=0?'fallen':''} ${targetable&&legal.includes(c.id)?'targetable':''} ${selected?'selected':''}" data-castle="${c.id}" data-side="${side}" ${!targetable||!legal.includes(c.id)?'disabled':''} ${targetable?`aria-pressed="${selected}"`:''} aria-label="${side==='enemy'?'Rakip':'Senin'} ${castleNames[c.id]}, ${c.hp} / ${c.maxHp} can${locked?', kilitli. Önce bir yan kuleyi yık.':''}${c.hp<=0?', yıkıldı':''}" title="${locked?'Önce bir yan kule yıkılmalı':c.hp<=0?'Kale yıkıldı':targetable?'Hedef seç':castleNames[c.id]}">${selected?'<span class="target-flag">HEDEFİN</span>':incoming?'<span class="target-flag">SALDIRI BURAYA</span>':locked?`<span class="locked-mark">${icon('lock')} KORUNUYOR</span>`:''}${castleArt(side,c.id==='main',c.hp<=0)}${c.hp>0?stationed.map((id,i)=>`<span class="hero-station ${i?'station-extra':''} ${state.heroes[side][id].retreatRounds?'retreating':''}" title="${HEROES[id].name}${state.heroes[side][id].retreatRounds?' ana kaleye çekiliyor':''}">${portrait(id)}</span>`).join(''):''}<span class="castle-name">${c.hp<=0?'Yıkıldı':castleNames[c.id]}</span><span class="castle-health ${c.hp/c.maxHp<.3?'low':''}"><span class="health-track"><span class="health-fill" style="width:${c.hp/c.maxHp*100}%"></span></span><span class="health-number">${c.hp}/${c.maxHp}</span></span></button>`;}).join('');}
function render(){safeSelection();const isDefense=state.phase==='playerDefense';const finished=state.phase==='finished';const isBusy=busy||['aiDefense','aiAttack'].includes(state.phase);const actions=isDefense?availableDefenses(state,'player'):availableAttacks(state,'player');const selected=isDefense?selectedDefense:selectedAttack;const action=actions.find(a=>a.id===selected);const attack=state.pendingAttack;
 $('enemy-castles').innerHTML=renderCastles('enemy');$('player-castles').innerHTML=renderCastles('player');
 $('round-banner').innerHTML=`<span class="round-label">${state.phase==='playerAttack'?'HAMLE SENDE':state.phase==='aiDefense'?'RAKİP SAVUNUYOR':state.phase==='aiAttack'?'RAKİP HAZIRLANIYOR':finished?'DÜELLO BİTTİ':'SAVUNMANI SEÇ'}</span><span class="round-token"><small>TUR</small>${String(state.round).padStart(2,'0')}</span>`;
 $('round-banner').hidden=isDefense;
 $('incoming-banner').hidden=!isDefense;
 if(isDefense)$('incoming-banner').innerHTML=`<strong>${icon(typeIcons[attack.type])}${HEROES[attack.heroId]?.name||'Rakip'} · ${esc(attack.label)}</strong><span>${types[attack.type]} saldırısı · ${castleNames[attack.targetId]} hedefte · ${attack.damage} ham hasar</span>`;
 $('arena-hint').textContent=finished?'':isDefense?'Muhafızlarından biri hedefteki her kaleyi koruyabilir.':isBusy?'Rakip de aynı bekleme süreleri ve kale kurallarıyla oynar.':'Rakibin bir yan kulesini yık, ana kaleye yolu aç.';
 $('bonus-label').className=`bonus-label ${state.training.power?'active':''}`;
 $('bonus-label').textContent=state.training.power?`✦ Kora: +${state.training.power*3} güç / +${state.training.defense*3} siper`:'Eğitim bonusu: '+(state.training.enabled?'yok':'kapalı');
 document.querySelector('.command-panel').classList.toggle('defense-mode',isDefense);document.querySelector('.command-panel').classList.toggle('busy-mode',isBusy);
 $('phase-eyebrow').textContent=finished?'DÜELLO TAMAMLANDI':isBusy?'RAKİBİN HAMLESİ':isDefense?'KALELERİN SANA EMANET':'SIRA SENDE';
 $('phase-title').textContent=finished?(state.winner==='player'?'Zafer senin!':'Yeniden ayağa kalk.'):isBusy?'Hamleler çözülüyor':isDefense?'Savunmanı seç':'Saldırını planla';
 $('phase-icon').innerHTML=icon(finished?'flag':isDefense?'shield':'stone');
 $('command-help').textContent=finished?'Her düello yeni bir hikâye. Hazırsan bir kez daha.':isBusy?(state.phase==='aiDefense'?'Rakip saldırına karşı savunmasını seçiyor.':'Rakip, hazır muhafızlarıyla bir karşı hamle hazırlıyor.'):isDefense?'Saldırı türünü eşleştir, daha çok hasarı engelle.':'Bir muhafız seç, rakibin yan kalesine nişan al.';
 if(state.phase==='playerAttack'&&legalTargets(state,'player').some(c=>c.id==='main'))$('command-help').textContent='Ana kaleye giden yol açıldı. Hedefini seç ve hamleni yap.';
 $('hero-choices').innerHTML=ids.map(id=>{const h=HEROES[id],hero=state.heroes.player[id],a=actions.find(a=>a.id===id),match=isDefense&&attack.type===a.type;const power=isDefense?previewDefense(state,id).blocked:a.damage;
 return `<button class="hero-card ${id} ${selected===id?'selected':''} ${match?'match':''}" data-hero="${id}" aria-pressed="${selected===id}" aria-label="${h.name}, ${a.name}, ${isDefense?power+' hasar engeller':power+' ham hasar'}. ${a.available?'Hazır':a.reason}" ${!a.available||isBusy||finished?'disabled':''}><span class="hero-portrait-wrap">${portrait(id)}</span><span class="hero-info"><span class="hero-topline"><span class="hero-name">${h.name}</span><span class="hero-type">${icon(typeIcons[h.type])}${types[h.type]}</span></span><span class="hero-action-name">${a.name}</span>${hero.retreatRounds?'<span class="unavailable-note">Ana kaleye çekiliyor</span>':`<span class="hero-cooldowns"><span class="${hero.attackCd?'cooldown-wait':''}">Saldırı ${hero.attackCd?'◷ '+hero.attackCd:'hazır'}</span><span class="${hero.defenseCd?'cooldown-wait':''}">Savunma ${hero.defenseCd?'◷ '+hero.defenseCd:'hazır'}</span></span>`}</span><span class="hero-power">${power}<small>${isDefense?'ENGELLER':'HASAR'}</small></span>${match?'<span class="match-badge">TÜR EŞLEŞMESİ</span>':''}</button>`;}).join('');
 const fallback=actions.find(a=>a.id===(isDefense?'brace':'rally'));$('fallback-button').className=`fallback-button ${selected===fallback.id?'selected':''}`;$('fallback-button').disabled=isBusy||finished;$('fallback-button').setAttribute('aria-pressed',String(selected===fallback.id));$('fallback-button').innerHTML=`${icon(isDefense?'shield':'flag')}<span>${fallback.name}<small>${isDefense?'Evrensel siper · özel savunmanı sakla':`${HEROES[fallback.heroId]?.name||'Muhafız'} · beklemeden kullanılabilir`}</small></span><span>${isDefense?'−'+fallback.block:fallback.damage}</span>`;
 if(finished){$('move-preview').innerHTML=`<div class="preview-row"><span>Düello süresi</span><strong>${state.round} tur</strong></div><div class="preview-row"><span>Kazanan</span><strong>${state.winner==='player'?'Senin krallığın':'Kızıl Sancak'}</strong></div>`;}
 else if(isDefense){const p=previewDefense(state,selectedDefense);$('move-preview').innerHTML=`<div class="preview-row"><span>Hedef: <strong>${castleNames[attack.targetId]}</strong></span><span><s>${p.incoming}</s> → <strong class="damage-value">${p.damage} hasar</strong></span></div><div class="preview-row"><span>${p.effective?'Tür eşleşmesi · güçlü siper':selectedDefense==='brace'?'Evrensel · bekleme yok':'⚠ Tür eşleşmiyor · savunma başarısız'}</span><strong class="block-value">${p.blocked} engellenir</strong></div>`;}
 else{$('move-preview').innerHTML=`<div class="preview-row"><span>Hedef</span><strong>${castleNames[selectedTarget]}</strong></div><div class="preview-row"><span>${action?.name||'Hamle seç'}</span><strong class="damage-value">${action?.damage||0} ham hasar</strong></div>`;}
 $('action-button').disabled=!finished&&(isBusy||!action?.available);$('action-button').innerHTML=finished?`${icon('refresh')} Yeniden oyna`:isBusy?`Hamle sürüyor <span class="waiting-dot"></span>`:isDefense?`${icon('shield')} ${castleNames[attack.targetId]}yi koru`.replace('kaleyi','kaleyi'):`${icon(typeIcons[action?.type]||'stone')} ${action?.id==='rally'?'Temel atış yap':action?.id==='kora'?'Kayayı savur':action?.id==='ilda'?'Okları gönder':'Yankıyı serbest bırak'}`;
 if(isDefense)$('action-button').innerHTML=`${icon('shield')} Savunmayı uygula`;
 $('action-note').textContent=finished?'Kahramanların bir sonraki düello için hazır.':isBusy?'Her hamle sırayla oynanır. Acele etmene gerek yok.':isDefense?(selectedDefense!=='brace'&&!previewDefense(state,selectedDefense).effective?'Yanlış tür: 0 koruma. Özel savunman yine beklemeye girer.':'Savunma, saldırı bekleme süresinden bağımsızdır.'):'Rakibin savunması, göstergede yazan hasarı azaltabilir.';
 $('battle-log').innerHTML=[...state.log].reverse().map(text=>`<li>${esc(text)}</li>`).join('');
 $('battle-flavor').textContent=finished?(state.winner==='player'?'Bugün bu topraklarda senin sancağın dalgalanıyor.':'Her yıkılan sur, daha güçlü bir dönüşün başlangıcıdır.'):isDefense?'Cesaret, saldırıyı görmek ve yerinden kıpırdamamaktır.':'Bir krallığı surları değil, onu savunanlar ayakta tutar.';
 persist();
}
function point(side,id){const arena=$('arena').getBoundingClientRect(),el=document.querySelector(`[data-side="${side}"][data-castle="${id}"]`).getBoundingClientRect();return{x:el.left-arena.left+el.width/2,y:el.top-arena.top+el.height*.5};}
function effect(attack,event){if(!attack)return;const targetSide=attack.side==='player'?'enemy':'player';const sourceId=state.heroes[attack.side][attack.heroId]?.castleId||'main';const s=point(attack.side,sourceId),t=point(targetSide,attack.targetId);const token=generation;const projectile=document.createElement('span');projectile.className=`projectile ${attack.type}`;projectile.style.cssText=`--sx:${s.x}px;--sy:${s.y}px;--tx:${t.x}px;--ty:${t.y}px`;projectile.innerHTML=icon(typeIcons[attack.type]);$('effects').append(projectile);
 schedule(()=>{projectile.remove();if(token!==generation)return;const target=document.querySelector(`[data-side="${targetSide}"][data-castle="${attack.targetId}"]`);target?.classList.add(event.castleFell?'falling':'hit');const label=document.createElement('span');label.className='hit-label';label.style.cssText=`--tx:${t.x}px;--ty:${t.y}px`;label.innerHTML=`<small>${event.blocked} engellendi</small>−${event.damage}`;$('effects').append(label);if(event.blocked){const shield=document.createElement('span');shield.className='shield-effect';shield.style.cssText=`--tx:${t.x}px;--ty:${t.y}px`;shield.innerHTML=icon('shield');$('effects').append(shield);schedule(()=>shield.remove(),700);}sound(event.effective?'defend':'hit');schedule(()=>label.remove(),1350);},reducedMotion.matches?20:440);
}
function finish(){busy=false;render();announce(state.winner==='player'?'Zafer! Rakibin ana kalesini yıktın.':'Ana kalen düştü. Düello bitti.');if(state.winner==='player'){sound('win');if(!reducedMotion.matches)for(let i=0;i<30;i++){const p=document.createElement('span');p.className='confetti';p.style.cssText=`--x:${Math.random()*100}%;--c:${['#e4be79','#88c5b4','#d99bab'][i%3]};--delay:${Math.random()*.6}s`;$('effects').append(p);}}if(!finishShown){finishShown=true;schedule(showFinish,1100);}}
function driveAI(){if(state.phase==='finished'){finish();return;}if(state.phase==='aiDefense'){busy=true;render();schedule(()=>{const attack=state.pendingAttack;try{state=resolveAiDefense(state);render();effect(attack,state.lastEvent);announce(`Rakip ${state.lastDefense.name} kullandı. ${state.lastEvent.damage} hasar verdin.`);if(state.phase==='finished'){schedule(finish,650);return;}schedule(driveAI,1000);}catch(error){recover(error);}},600);}else if(state.phase==='aiAttack'){busy=true;render();schedule(()=>{try{state=chooseAiAttack(state);busy=false;selectedDefense=availableDefenses(state,'player').find(d=>d.available&&d.type===state.pendingAttack.type)?.id||'brace';render();announce(`${HEROES[state.pendingAttack.heroId]?.name||'Rakip'}, ${types[state.pendingAttack.type]} saldırısıyla ${castleNames[state.pendingAttack.targetId]}ni hedefliyor. ${state.pendingAttack.damage} ham hasar. Savunmanı seç.`);}catch(error){recover(error);}},700);}else{busy=false;render();}}
function recover(error){console.error(error);cancelTimers();busy=false;toast('Bu hamle tamamlanamadı. Düelloyu yeniden başlatabilirsin.');render();}
function takeAction(){if(busy)return;if(state.phase==='finished'){newGame();return;}if(state.phase==='playerAttack'){try{state=playerAttack(state,{attackId:selectedAttack,targetId:selectedTarget});busy=true;render();sound('select');driveAI();}catch(error){toast(error.message);}}else if(state.phase==='playerDefense'){try{busy=true;const attack=state.pendingAttack;state=playerDefend(state,{defenseId:selectedDefense});render();effect(attack,state.lastEvent);announce(`${state.lastEvent.blocked} hasar engellendi, kalen ${state.lastEvent.damage} hasar aldı.`);if(state.phase==='finished')schedule(finish,750);else schedule(()=>{busy=false;render();announce(`${state.round}. tur. Saldırı sırası sende.`);},850);}catch(error){busy=false;toast(error.message);render();}}}
function newGame(){cancelTimers();closeModal();state=freshGame();selectedAttack='kora';selectedTarget='left';selectedDefense='brace';busy=false;finishShown=false;render();announce('Yeni düello başladı. İlk saldırını seç.');}
$('arena').addEventListener('click',e=>{const b=e.target.closest('[data-castle]');if(!b||b.disabled||busy||state.phase!=='playerAttack')return;selectedTarget=b.dataset.castle;render();sound('select');});
$('hero-choices').addEventListener('click',e=>{const b=e.target.closest('[data-hero]');if(!b||b.disabled||busy)return;if(state.phase==='playerDefense')selectedDefense=b.dataset.hero;else selectedAttack=b.dataset.hero;render();sound('select');});
$('fallback-button').addEventListener('click',()=>{if(busy)return;if(state.phase==='playerDefense')selectedDefense='brace';else selectedAttack='rally';render();});
$('action-button').addEventListener('click',takeAction);
$('sound-button').addEventListener('click',()=>{settings.sound=!settings.sound;setSoundIcon();persist();if(settings.sound)sound('select');toast(settings.sound?'Ses açık. Muhafızların hazır.':'Ses kapalı.');});
$('log-toggle').addEventListener('click',()=>{const expanded=document.querySelector('.chronicle').classList.toggle('expanded');$('log-toggle').setAttribute('aria-expanded',String(expanded));});
function openModal(html){modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;$('modal-content').innerHTML=html;const heading=$('modal-content').querySelector('h2');if(heading){heading.id='modal-title';$('modal').setAttribute('aria-labelledby','modal-title');}if(!$('modal').open)$('modal').showModal();}
function closeModal(){modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;$('modal').close();}
$('close-modal').addEventListener('click',closeModal);$('modal').addEventListener('cancel',()=>{modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function help(){openModal(`<div class="eyebrow">MUHAFIZIN EL KİTABI</div><h2>Üç kale. Tek zafer.</h2><p>Karşında Kızıl Sancak var. Üç muhafızının yeteneklerini sırayla kullan, rakibin ana kalesini yık.</p><div class="help-steps"><div class="help-step"><span>1</span><div><strong>Önce yolu aç.</strong><p>Bir kahraman ve bir rakip yan kule seç. Yan kulelerden biri yıkılınca ana kale hedef alınabilir.</p></div></div><div class="help-step"><span>2</span><div><strong>Saldırıyı oku, türünü eşleştir.</strong><p>Rakibin kahramanı, saldırı türü, hedefi ve ham hasarı açıkça gösterilir. Her muhafız, kendi türündeki saldırıya karşı güçlü savunur. Yanlış türde özel savunma başarısız olur: 0 hasar engeller ve beklemeye girer. Evrensel kalkan her türe karşı 12 engeller. Dilediğin muhafız, hedefteki her kaleyi koruyabilir.</p></div></div><div class="help-step"><span>3</span><div><strong>Bekleme sürelerini yönet.</strong><p>Saldırı ve savunma ayrı ayrı bekler. Özel yetenek için araya bir tam tur koymalısın. Temel Atış ve Kalkanları Kaldır her zaman hazırdır; onları seçerek özel yeteneğini saklayabilirsin.</p></div></div></div><div class="rule-pair"><span class="rule-pill">${icon('stone')} Kora · Taş</span><span class="rule-pill">${icon('arrow')} İlda · Ok</span><span class="rule-pill">${icon('sound')} Neris · Ses</span></div><p class="modal-note">Can kahramanlarda değil, kalelerdedir. Yan kalesi yıkılan muhafız ana kaleye çekilir; o turun kalanı ve sonraki tam tur dinlenir, sonra geri döner. Rakip de aynı kuralları kullanır. Sıra: sen saldır → rakip savun → rakip saldır → sen savun.</p><button class="primary-button" data-modal-action="close">Anladım, krallık beni bekliyor ${icon('chevron')}</button>`);}
$('help-button').addEventListener('click',help);
function stories(){openModal(`<div class="eyebrow">ÜÇ FARKLI HİKÂYE, BİR SANCAK</div><h2>Muhafızlarını tanı.</h2><p>Onlar sadece surların üzerinde durmaz. Her biri, koruduğu topraklardan bir parça taşır.</p><div class="story-heroes"><div class="story-hero">${portrait('kora')}<div><h3>Kora <small>TAŞ MUHAFIZI</small></h3><p>Dağ köyünün son taş ustası. Yıktığı her duvar için bir köprü kuracağına söz verdi. Sabırlı, inatçı, beklenmedik kadar nazik.</p><em>“Sağlam dur. Gerisini ben hallederim.”</em></div></div><div class="story-hero">${portrait('ilda')}<div><h3>İlda <small>OK USTASI</small></h3><p>Ormanın kayıp patikalarını ezbere bilir. Bir zamanlar habercilik yapardı; şimdi okları rüzgârdan önce varır. Hızlı düşünür, meydan okumayı sever.</p><em>“Rüzgâr bir şey söylüyor. Ben duydum.”</em></div></div><div class="story-hero">${portrait('neris')}<div><h3>Neris <small>YANKI KORUYUCUSU</small></h3><p>Sessiz Göl’ün çanlarını yeniden çaldıran gezgin. Sesiyle taşı titreştirir, sessizliğiyle saldırıyı durdurur. Sakin, meraklı ve biraz muzip.</p><em>“En güçlü ses, doğru anda duyulandır.”</em></div></div></div><button class="primary-button" data-modal-action="close">Muhafızlara dön ${icon('chevron')}</button>`);}
$('stories-button').addEventListener('click',stories);
$('enemy-info-button').addEventListener('click',()=>{openModal(`<div class="eyebrow">KIZIL SANCAK · AÇIK BİLGİ</div><h2>Rakibini tanı.</h2><p>Rakip seninle aynı can, saldırı, savunma ve bekleme kurallarına uyar. Her iki taraf da bu bilgileri kullanabilir.</p><div class="story-heroes">${ids.map(id=>{const h=state.heroes.enemy[id];return `<div class="story-hero">${portrait(id)}<div><h3>${HEROES[id].name} <small>${types[HEROES[id].type].toLocaleUpperCase('tr')}</small></h3><p>${castleNames[h.castleId]}${h.retreatRounds?' · Ana kaleye çekiliyor':''}<br>Saldırı: ${h.attackCd?h.attackCd+' tur bekleme':'hazır'} · ${ATTACKS[id].damage} ham hasar<br>Savunma: ${h.defenseCd?h.defenseCd+' tur bekleme':'hazır'} · ${DEFENSES[id].block} eşleşen siper</p></div></div>`;}).join('')}</div><p class="modal-note">Rakip gizli bir kararını okumaz. Hazır savunmalarını ve kale canlarını görür; zayıf noktaları, açık ana kaleyi ve farklı saldırı türlerini değerlendirir. Eğitim bonusu yalnızca sana uygulanır ve kapatılabilir.</p><button class="primary-button" data-modal-action="close">Düelloya dön</button>`);});

function settingsModal(){openModal(`<div class="eyebrow">KENDİ TEMPOUNDA OYNA</div><h2>Düello ayarları</h2><div class="settings-row"><div><strong>Eğitim bonusları</strong><small>${settings.bestTraining?'Kora’nın en iyi talimi: +'+settings.bestTraining*3+' güç / +'+settings.bestTraining*3+' eşleşen siper.':'Henüz eğitim bonusun yok. Kora’nın talim alanında kazanabilirsin.'}<br>Değişiklik yeni düelloda uygulanır.</small></div><input class="toggle" id="bonus-toggle" type="checkbox" ${settings.trainingEnabled?'checked':''} aria-label="Yeni düellolarda eğitim bonusunu uygula"></div><div class="settings-row"><div><strong>Ses efektleri</strong><small>Yalnızca bu cihazda saklanır.</small></div><input class="toggle" id="sound-toggle" type="checkbox" ${settings.sound?'checked':''} aria-label="Ses efektlerini aç"></div><div class="settings-row"><div><strong>Bu düellodaki Kora bonusu</strong><small>Güç +${state.training.power*3} · eşleşen siper +${state.training.defense*3}.<br>Karşılaştırmak için bonusu aç/kapat ve yeni düello başlat.</small></div></div><div class="settings-actions"><button class="primary-button" data-modal-action="new">${icon('refresh')} Bu ayarlarla yeni düello</button><button class="secondary-button danger-button" data-modal-action="reset-confirm">Bu cihazdaki ilerlemeyi temizle</button></div><p style="margin-top:17px;font-size:9px">Hesap, ödeme veya çevrimiçi bağlantı gerekmez. Düello ve talim kaydın bu tarayıcıda tutulur.${storageAvailable?'':' Bu tarayıcı kayıt alanına izin vermedi; ilerleme sekme kapandığında kaybolabilir.'}</p>`);
 $('bonus-toggle').addEventListener('change',e=>{settings.trainingEnabled=e.target.checked;persist();});$('sound-toggle').addEventListener('change',e=>{settings.sound=e.target.checked;setSoundIcon();persist();if(settings.sound)sound('select');});}
$('settings-button').addEventListener('click',settingsModal);
function resetConfirm(){openModal(`<div class="eyebrow">YENİ BİR SAYFA</div><h2>İlerleme temizlensin mi?</h2><p>Bu tarayıcıdaki düello, eğitim derecesi ve ses ayarı silinir. Bu işlemi geri alamazsın. Diğer sitelerin verilerine dokunulmaz.</p><button class="primary-button" data-modal-action="reset">Evet, ilerlemeyi temizle</button><button class="secondary-button" data-modal-action="settings" style="width:100%;margin-top:12px">Vazgeç</button>`);}
function showFinish(){if(state.phase!=='finished')return;const won=state.winner==='player',standing=state.castles.player.filter(c=>c.hp>0).length;openModal(`<div class="win-content"><div class="modal-crest">${icon(won?'flag':'shield')}</div><div class="eyebrow" style="justify-content:center">${won?'SANCAGIN YÜKSELİYOR':'BU HİKÂYE BURADA BİTMİYOR'}</div><h2>${won?'Krallık güvende.':'Bir sonraki hamlen.'}</h2><p>${won?'Kızıl Sancak’ın ana kalesi düştü. Muhafızların bu zaferi birlikte kazandı.':'Ana kalen düştü. Yeni düelloda farklı saldırı türlerini sırayla kullan; eşleşen savunmanı doğru ana sakla.'}</p><div class="win-stats"><div><strong>${state.round}</strong><small>TUR</small></div><div><strong>${standing}</strong><small>AYAKTA KALE</small></div><div><strong>+${state.training.power*3}</strong><small>KORA BONUSU</small></div></div><button class="primary-button" data-modal-action="new">${icon('refresh')} Bir düello daha</button><button class="secondary-button" data-modal-action="close">Savaş alanına bak</button></div>`);}
function training(){openModal(`<div class="training-header">${portrait('kora')}<div><div class="eyebrow">KORA’NIN TALİM ALANI</div><h2>Gücünü zamanla.</h2><p>İşaretçi ortadaki altın alana geldiğinde vur. Üç atış, tek derece.</p></div></div><div class="training-range"><span class="training-zone"></span><span id="training-marker" class="training-marker"></span></div><p class="training-instructions">En iyi isabet için tam ortayı hedefle. Süre sınırı yok.</p><div class="training-shots" id="training-shots"><span class="training-shot">1</span><span class="training-shot">2</span><span class="training-shot">3</span></div><button class="primary-button" id="training-hit">${icon('stone')} Şimdi vur!</button><div id="training-feedback" role="status" aria-live="polite" style="text-align:center;min-height:25px;margin-top:13px;font-size:11px;color:var(--gold)">Hazır olduğunda ilk atışını yap.</div><p class="modal-note" style="margin-top:18px">En iyi derecen saklanır. En fazla +9 saldırı ve +9 eşleşen siper kazanırsın. Bonus yalnızca yeni düelloda uygulanır ve ayarlardan kapatılabilir.</p>`);
 trainingSession={start:performance.now(),position:.5,scores:[],lock:false};const tick=now=>{if(!trainingSession||!$('modal').open)return;trainingSession.position=.5+Math.sin((now-trainingSession.start)/(580-trainingSession.scores.length*70))*.47;const marker=$('training-marker');if(marker)marker.style.left=trainingSession.position*100+'%';trainingFrame=requestAnimationFrame(tick);};trainingFrame=requestAnimationFrame(tick);$('training-hit').addEventListener('click',trainingHit);}
function trainingHit(){const session=trainingSession;if(!session||session.lock)return;session.lock=true;const distance=Math.abs(session.position-.5),score=distance<=.08?100:distance<=.2?65:25;session.scores.push(score);sound(score===100?'defend':'hit');$('training-shots').innerHTML=[0,1,2].map(i=>`<span class="training-shot ${i<session.scores.length?'done':''}">${session.scores[i]===100?'✦':session.scores[i]===65?'✓':session.scores[i]===25?'·':i+1}</span>`).join('');$('training-feedback').textContent=score===100?'Tam isabet! Taş bile gülümsedi.':score===65?'İyi atış. Merkeze biraz daha yaklaş.':'Kaya hedefi sıyırdı. Bir sonraki atış senin.';
 if(session.scores.length===3){cancelAnimationFrame(trainingFrame);const average=session.scores.reduce((a,b)=>a+b,0)/3,tier=average>=90?3:average>=65?2:average>=35?1:0;settings.bestTraining=Math.max(settings.bestTraining,tier);persist();trainingSession=null;$('training-hit').disabled=true;const expectedModal=modalGeneration;setTimeout(()=>{if(modalGeneration!==expectedModal||!$('modal').open||!$('training-hit'))return;openModal(`<div class="eyebrow">TALİM TAMAMLANDI</div><h2>${tier===3?'Taş gibi isabet.':tier===2?'Bileğin güçleniyor.':tier===1?'İlk adım atıldı.':'Bir daha deneyelim.'}</h2><p>Kora: “${tier>=2?'Sabır ve doğru an. İşte bütün sır bu.':'Her atış bir şey öğretir. Bir daha deneyelim.'}”</p><div class="training-result"><div class="star-row">${'★'.repeat(tier)}${'☆'.repeat(3-tier)}</div><strong>+${tier*3} güç · +${tier*3} siper</strong><p>Bu talimde kazandığın derece<br>En iyi kaydın: +${settings.bestTraining*3} güç ve +${settings.bestTraining*3} eşleşen siper</p></div><p class="modal-note">“Yeni düello” mevcut savaşı sıfırlar ve en iyi talim bonusunu açar. Dilersen mevcut düellona bonus değiştirmeden dönebilirsin.</p><button class="primary-button" data-modal-action="training-new">${icon('flag')} Bonusla yeni düello</button><button class="secondary-button" data-modal-action="training" style="width:100%;margin-top:12px">Yeniden talim yap</button><button class="text-button" data-modal-action="close" style="width:100%;text-align:center">Mevcut düelloya dön</button>`);},800);
 }else{setTimeout(()=>{if(trainingSession===session)session.lock=false;},350);}}
$('training-button').addEventListener('click',training);
$('modal-content').addEventListener('click',e=>{const a=e.target.closest('[data-modal-action]')?.dataset.modalAction;if(!a)return;if(a==='close')closeModal();else if(a==='new')newGame();else if(a==='settings')settingsModal();else if(a==='reset-confirm')resetConfirm();else if(a==='reset'){settings={sound:false,trainingEnabled:true,bestTraining:0};try{localStorage.removeItem(STORE);}catch{}setSoundIcon();newGame();toast('İlerleme temizlendi. Yepyeni bir düello.');}else if(a==='training')training();else if(a==='training-new'){settings.trainingEnabled=true;newGame();}});
window.addEventListener('pagehide',persist);
render();
if(['aiDefense','aiAttack'].includes(state.phase))driveAI();else if(state.phase==='finished'){finishShown=true;}
if(!storageAvailable)toast('Bu tarayıcı ilerlemeyi kaydetmeye izin vermiyor. Düellon açık sekmede devam eder.');
